private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Validate the start index
    if (i < 0 || i >= bb.limit()) {
        return i;
    }

    int remaining = bb.limit() - i;
    if (remaining <= 0) {
        return i;
    }

    byte b0 = bb.get(i);
    int consumed = 1;
    int codePoint;

    // Single-byte (ASCII)
    if (b0 >= 0) {
        codePoint = b0 & 0x7F;
    }
    // Two-byte sequence
    else if ((b0 & 0xE0) == 0xC0) {
        if (remaining < 2) {
            return i; // incomplete sequence
        }
        byte b1 = bb.get(i + 1);
        if ((b1 & 0xC0) != 0x80) {
            codePoint = 0xFFFD; // replacement character
        } else {
            codePoint = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
            consumed = 2;
        }
    }
    // Three-byte sequence
    else if ((b0 & 0xF0) == 0xE0) {
        if (remaining < 3) {
            return i; // incomplete sequence
        }
        byte b1 = bb.get(i + 1);
        byte b2 = bb.get(i + 2);
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
            codePoint = 0xFFFD;
        } else {
            codePoint = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
            consumed = 3;
        }
    }
    // Four-byte sequence
    else if ((b0 & 0xF8) == 0xF0) {
        if (remaining < 4) {
            return i; // incomplete sequence
        }
        byte b1 = bb.get(i + 1);
        byte b2 = bb.get(i + 2);
        byte b3 = bb.get(i + 3);
        if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80)) {
            codePoint = 0xFFFD;
            consumed = 1;
        } else {
            codePoint = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12)
                    | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            // Convert to surrogate pair
            codePoint -= 0x10000;
            int high = 0xD800 + (codePoint >> 10);
            int low = 0xDC00 + (codePoint & 0x3FF);
            sb.append((char) high);
            sb.append((char) low);
            return i + 4;
        }
    }
    // Invalid first byte
    else {
        codePoint = 0xFFFD;
    }

    sb.append((char) codePoint);
    return i + consumed;
}

