        throw new IllegalArgumentException("Graph must not be null");
    }
    Map<V,V> vertexMap = new HashMap<>();
    Map<E,E> edgeMap = new HashMap<>();
    for (V v : graph.getVertices()) {
        vertexMap.put(v, v);
