@Override @SuppressWarnings("unchecked") public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null) throw new IllegalArgumentException("Target graph cannot be null.");
    if (resultMap == null) throw new IllegalArgumentException("Result map cannot be null.");

    // Define the two partitions of the bipartite graph
    String[] leftPart  = {"L1", "L2", "L3"};
    String[] rightPart = {"R1", "R2", "R3"};

    try {
        // Clear existing graph structure
        target.removeAllEdges(target.edgeSet());
        target.removeAllVertices(target.vertexSet());

        // Add vertices and store in the result map
        for (String name : leftPart) {
            V v = (V) name;
            target.addVertex(v);
            resultMap.put(name, v);
        }
        for (String name : rightPart) {
            V v = (V) name;
            target.addVertex(v);
            resultMap.put(name, v);
        }

        // Connect every vertex in the left partition to every vertex in the right partition
        for (String lName : leftPart) {
            for (String rName : rightPart) {
                V v1 = resultMap.get(lName);
                V v2 = resultMap.get(rName);
                target.addEdge(v1, v2);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to generate complete bipartite graph.", e);
    }
}

