int addType(final String value){
    if (value == null) {
        throw new IllegalArgumentException("Type value cannot be null");
    }
    try {
        // Ensure the type table is initialized
        if (typeTable == null) {
            // Assuming typeTable is an ArrayList<Symbol>; use fully qualified name to avoid imports
            typeTable = new java.util.ArrayList<>();
        }
        // Search for an existing type with the same value
        for (int i = 0; i < typeTable.size(); i++) {
            Symbol sym = typeTable.get(i);
            if (sym != null && value.equals(sym.getValue())) {
                return i; // Found existing entry, return its index
            }
        }
        // No existing type found, create a new one
        Symbol newSym = new Symbol(value);
        typeTable.add(newSym);
        return typeTable.size() - 1; // Return the index of the newly added type
    } catch (Exception e) {
        // Propagate any unexpected exceptions as runtime exceptions
        throw new RuntimeException("Unable to add type: " + e.getMessage(), e);
    }
}

