public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        // Guard against null input
        if (mappings == null) {
            return null;
        }

        // Retrieve the properties map from the historical (current) mapping.
        Map<String, Object> currentProps = mappings.getProperties();
        if (currentProps == null) {
            currentProps = new HashMap<>();
        }

        // Retrieve the desired mapping for the table. In a real implementation this
        // might come from a configuration store or another service. Here we assume
        // a static method that provides the latest mapping.
        Mappings desired = MappingProvider.getMappingForTable(tableName);
        if (desired == null) {
            return null; // nothing to diff
        }

        Map<String, Object> desiredProps = desired.getProperties();
        if (desiredProps == null) {
            return null;
        }

        // Build the diff: fields present in the desired mapping but not in the current one.
        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : desiredProps.entrySet()) {
            String field = entry.getKey();
            if (!currentProps.containsKey(field)) {
                diffProps.put(field, entry.getValue());
            }
        }

        // If no new fields, there is nothing to update.
        if (diffProps.isEmpty()) {
            return null;
        }

        // Construct a new Mappings instance representing only the added fields.
        Mappings diff = new Mappings();

        // Remove or disable the _source config to avoid conflict during index update.
        // Assuming a method setSource(Object) exists; if it accepts null or false,
        // this disables _source. Adjust according to actual API.
        diff.setSource(null);

        // Set the diff properties.
        diff.setProperties(diffProps);

        return diff;
    } catch (Exception e) {
        // Log the error and wrap it in a runtime exception or return null if desired.
        // Logging is omitted here to keep the method self-contained.
        throw new RuntimeException("Failed to compute mapping diff for table " + tableName, e);
    }
}

