protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    try {
        if (FETCH_DATA_DURATION <= 0) {
            throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
        }
        if (start > end) {
            return ranges; // empty list if start is after end
        }
        long current = start;
        while (current <= end) {
            long potentialEnd;
            // avoid overflow when adding FETCH_DATA_DURATION
            if (current > Long.MAX_VALUE - FETCH_DATA_DURATION) {
                potentialEnd = end;
            } else {
                potentialEnd = Math.min(current + FETCH_DATA_DURATION, end);
            }
            ranges.add(new TimeRange(current, potentialEnd));
            if (potentialEnd == end) {
                break;
            }
            current = potentialEnd + 1; // move to the next millisecond after the current range
        }
    } catch (Exception e) {
        // You could log the exception here if a logging framework is available
        // For now we rethrow it wrapped in a RuntimeException to avoid silent failures
        throw new RuntimeException("Failed to build time ranges", e);
    }
    return ranges;
}

