static long compressTimeBucket(long timeBucket,int dayStep){
    if(timeBucket <= 0){
        throw new IllegalArgumentException("timeBucket must be a positive long representing a date in yyyymmdd format");
    }
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    if(month < 1 || month > 12 || day < 1 || day > 31){
        throw new IllegalArgumentException("timeBucket does not represent a valid date");
    }
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen || index + len > strLen) {
        throw new IndexOutOfBoundsException(
                "Requested range index=" + index + ", length=" + len + " exceeds input length " + strLen);
    }
    int end = index + len;
    int byteCount = 0;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        int codePoint;
        if (ch <= 0x7F) {
            // ASCII
            byteCount += 1;
            continue;
        }
        if (ch <= 0x7FF) {
            // 2-byte sequence
            byteCount += 2;
            continue;
        }
        // char > 0x7FF
        if (Character.isHighSurrogate(ch)) {
            // Potential surrogate pair
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    // Valid surrogate pair representing a code point > U+FFFF -> 4 bytes
                    byteCount += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            // Unpaired high surrogate, treat as 3 bytes (as per UTF-8 surrogate replacement)
            byteCount += 3;
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate, treat as 3 bytes
            byteCount += 3;
        } else {
            // BMP non-ASCII character -> 3 bytes
            byteCount += 3;
        }
    }
    return byteCount;
}

