    // Validate length
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // If nothing to copy, just return this
    if (byteLength == 0) {
        return this;
    }
    // Ensure we can accommodate the new data
    int newSize = size + byteLength;
    ensureCapacity(newSize);

    if (byteArrayValue == null) {
        // Fill with null bytes (zeros)
        for (int i = 0; i < byteLength; i++) {
            buf[size + i] = 0;
        }
    } else {
        // Validate offset and bounds
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new ArrayIndexOutOfBoundsException(
                "Invalid offset/length for the provided byte array");
        }
        System.arraycopy(byteArrayValue, byteOffset, buf, size, byteLength);
    }

    // Update size of the vector
    size = newSize;
    return this;
}

