            try {
                putMethod = lbClass.getMethod("put", byte[].class, int.class, int.class);
            } catch (NoSuchMethodException e2) {
                // Fall back to byte-by-byte writing if append(byte) exists
                try {
                    java.lang.reflect.Method appendMethod = lbClass.getMethod("append", byte.class);
                    for (byte b : utf8Bytes) {
                        appendMethod.invoke(lb, b);
                    }
                    return lb;
                } catch (NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException ex) {
                    throw new RuntimeException("LinkedBuffer does not support writing bytes", ex);
