            nextTreeEdge.prevTreeEdge = prevTreeEdge;
        }

        // Detach this edge from the list of the second endpoint
        if (prevTreeEdgeOther != null) {
            prevTreeEdgeOther.nextTreeEdgeOther = nextTreeEdgeOther;
        }
        if (nextTreeEdgeOther != null) {
            nextTreeEdgeOther.prevTreeEdgeOther = prevTreeEdgeOther;
