private static String substitute(String value, Properties props, java.util.Set<String> visited) {
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    java.lang.StringBuffer result = new java.lang.StringBuffer();
    while (matcher.find()) {
        String subKey = matcher.group(1).trim();
        String subValue;
        if (visited.contains(subKey)) {
            // Infinite recursion detected; leave placeholder unchanged
            subValue = matcher.group(0);
        } else {
            String propVal = props.getProperty(subKey);
            if (propVal == null) {
                // Undefined property; replace with empty string
                subValue = "";
            } else {
                visited.add(subKey);
                subValue = substitute(propVal, props, visited);
                visited.remove(subKey);
            }
        }
        matcher.appendReplacement(result, java.util.regex.Matcher.quoteReplacement(subValue));
    }
    matcher.appendTail(result);
    return result.toString();
}

