public static java.util.List<PathSegmentImpl> decodePath(java.net.URI u, boolean decode) {
    if (u == null) {
        return java.util.Collections.emptyList();
    }
    java.lang.String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    // Remove leading '/' if present (absolute path)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    java.util.List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    // Split on '/' preserving empty segments (e.g., trailing slash)
    java.lang.String[] parts = path.split("/", -1);
    for (java.lang.String part : parts) {
        if (part.isEmpty()) {
            // Skip empty segments that result from consecutive slashes or a trailing slash
            continue;
        }
        java.lang.String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported; fallback to raw value
            }
        }
        // Assuming PathSegmentImpl has a constructor that takes the segment string
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

