private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    int pos = 0;
    final int len = descriptor.length();
    try {
        if (len == 0) {
            throw new IllegalArgumentException("Empty descriptor");
        }
        /* Helper lambda to pop the required number of slots from the output frame stack */
        java.util.function.IntConsumer popSlots = (slots) -> {
            while (slots-- > 0) {
                outputFrame.pop(); // assumes a stack field named outputFrame
            }
        };

        if (descriptor.charAt(0) == '(') {  // method descriptor
            pos = 1;
            /* Parse argument types until the closing ')' */
            while (pos < len && descriptor.charAt(pos) != ')') {
                char c = descriptor.charAt(pos);
                if (c == 'L') {  // object type
                    int semicolon = descriptor.indexOf(';', pos);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Malformed descriptor: missing ';' for object type");
                    }
                    popSlots.accept(1);
                    pos = semicolon + 1;
                } else if (c == '[') {  // array type
                    pos++; // consume '['
                    while (pos < len && descriptor.charAt(pos) == '[') {
                        pos++;
                    }
                    if (pos >= len) {
                        throw new IllegalArgumentException("Malformed descriptor: incomplete array type");
                    }
                    char t = descriptor.charAt(pos);
                    if (t == 'L') {
                        int semicolon = descriptor.indexOf(';', pos);
                        if (semicolon == -1) {
                            throw new IllegalArgumentException("Malformed descriptor: missing ';' for object array type");
                        }
                        pos = semicolon + 1;
                    } else {
                        pos++; // consume primitive type within array
                    }
                    popSlots.accept(1); // arrays take one stack slot
                } else {  // primitive type
                    int slots = (c == 'J' || c == 'D') ? 2 : 1;
                    popSlots.accept(slots);
                    pos++;
                }
            }
            /* Skip the return type; it is not popped */
            if (pos >= len || descriptor.charAt(pos) != ')') {
                throw new IllegalArgumentException("Malformed descriptor: missing ')' in method descriptor");
            }
            pos++; // consume ')'
            if (pos < len) {
                // The return type is present but ignored
            }
        } else {  // single type descriptor
            char c = descriptor.charAt(pos);
            if (c == 'L') {  // object type
                int semicolon = descriptor.indexOf(';', pos);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Malformed descriptor: missing ';' for object type");
                }
                popSlots.accept(1);
                pos = semicolon + 1;
            } else if (c == '[') {  // array type
                pos++; // consume '['
                while (pos < len && descriptor.charAt(pos) == '[') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Malformed descriptor: incomplete array type");
                }
                char t = descriptor.charAt(pos);
                if (t == 'L') {
                    int semicolon = descriptor.indexOf(';', pos);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Malformed descriptor: missing ';' for object array type");
                    }
                    pos = semicolon + 1;
                } else {
                    pos++; // consume primitive type within array
                }
                popSlots.accept(1);
            } else {  // primitive type
                int slots = (c == 'J' || c == 'D') ? 2 : 1;
                popSlots.accept(slots);
                pos++;
            }
            if (pos != len) {
                throw new IllegalArgumentException("Descriptor contains unexpected trailing characters");
            }
        }
    } catch (IndexOutOfBoundsException | NullPointerException e) {
        throw new IllegalArgumentException("Failed to pop stack using descriptor: " + descriptor, e);
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Input byte array is null");
    }
    if (off < 0 || len < 0 || (off + len) > b.length) {
        throw new IndexOutOfBoundsException("Offset and/or length out of bounds");
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newSize = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newSize];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }
    if (i != j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

