        throw new IllegalArgumentException("Source vertex cannot be null");
    }
    if (targetVertex == null) {
        throw new IllegalArgumentException("Target vertex cannot be null");
    }
    if (e == null) {
        throw new IllegalArgumentException("Edge cannot be null");
    }

    try {
        // Lazily initialize the outer map if necessary
        Map<V, List<E>> targetMap = index.get(sourceVertex);
        if (targetMap == null) {
            targetMap = new HashMap<>();
            index.put(sourceVertex, targetMap);
        }

        // Lazily initialize the inner list for the target vertex
        List<E> edgeList = targetMap.get(targetVertex);
        if (edgeList == null) {
            edgeList = new ArrayList<>();
            targetMap.put(targetVertex, edgeList);
        }

        // Add the edge to the list
        edgeList.add(e);
    } catch (RuntimeException ex) {
        // Wrap and rethrow to preserve original exception details
        throw new RuntimeException("Failed to add edge to index: " + ex.getMessage(), ex);
    }
}

