public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    double minX = box.getMinX();
    double minY = box.getMinY();
    double maxX = box.getMaxX();
    double maxY = box.getMaxY();

    if (minX >= maxX) {
        throw new IllegalArgumentException("Box has non-positive width");
    }

    double midX = (minX + maxX) / 2.0;

    Box2D firstHalf = new Box2D(minX, minY, midX, maxY);
    Box2D secondHalf = new Box2D(midX, minY, maxX, maxY);

    return new Pair<>(firstHalf, secondHalf);
}

private void enlarge(final int size) {
    // Validate the requested additional size
    if (size < 0) {
        throw new IllegalArgumentException("Requested additional size must be non‑negative");
    }
    if (size == 0) {
        return; // nothing to do
    }

    try {
        // Current capacity of the underlying byte array (zero if uninitialised)
        int currentCapacity = (buffer != null) ? buffer.length : 0;

        // Compute a new capacity that guarantees room for the requested additional bytes.
        // We use a doubling strategy to keep amortised growth linear.
        int newCapacity = Math.max(currentCapacity * 2, currentCapacity + size);

        // Guard against integer overflow
        if (newCapacity < 0) { // overflow: set to the maximum positive int value
            newCapacity = Integer.MAX_VALUE;
        }

        byte[] newBuffer = new byte[newCapacity];

        // Copy existing data to the new buffer if it already exists
        if (buffer != null) {
            System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        }

        // Replace the old buffer with the enlarged one
        buffer = newBuffer;
    } catch (OutOfMemoryError e) {
        // Convert the low‑level error into a runtime exception that can be caught by callers
        throw new RuntimeException("Unable to enlarge byte vector due to insufficient memory", e);
    }
}

