public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        int len = current.write - current.read;
        if (len > 0) {
            out.write(current.buf, current.read, len);
            total += len;
        }
        current = current.next;
    }
    return total;
}

