@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }

    // Ensure we're requested to convert to Character (wrapper) or char (primitive)
    if (type != Character.class && type != char.class) {
        throw new ClassCastException("ConversionTarget is not Character or char");
    }

    // For primitive char, null is not allowed
    if (value == null) {
        if (type == char.class) {
            throw new IllegalArgumentException("Cannot convert null to primitive char");
        }
        return null; // null is acceptable for Character wrapper
    }

    // Direct conversion if already a Character
    if (value instanceof Character) {
        return value;
    }

    // From Number: cast numeric value to char
    if (value instanceof Number) {
        int numericValue = ((Number) value).intValue();
        return (char) numericValue;
    }

    // From String or CharSequence of length 1
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        }
        throw new IllegalArgumentException(
                "Cannot convert CharSequence with length != 1 to Character: " + value);
    }

    // Special case: single-element char array
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return arr[0];
        }
        throw new IllegalArgumentException(
                "Cannot convert char array with length != 1 to Character: " + java.util.Arrays.toString(arr));
    }

    // Fallback: try to use toString and get first character if single-char string
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    throw new IllegalArgumentException(
            "Cannot convert value to java.lang.Character: " + value);
}

