@Override
public String readString() throws IOException {
    // Read the length of the string as a signed 32‑bit integer
    int length;
    try {
        length = this.input.readInt();
    } catch (IOException e) {
        throw new IOException("Failed to read string length from stream", e);
    }

    // Validate the length
    if (length < 0) {
        throw new IOException("Negative string length encountered: " + length);
    }
    if (length == 0) {
        return "";
    }

    // Read the exact number of bytes and convert them to a UTF‑8 string
    byte[] bytes = new byte[length];
    try {
        this.input.readFully(bytes);
    } catch (IOException e) {
        throw new IOException("Failed to read string bytes from stream", e);
    }

    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

private static int digitValue(final char c) {
    int v;
    if (c >= '0' && c <= '9') {
        v = c - '0';
    } else if (c >= 'A' && c <= 'Z') {
        v = c - 'A' + 10;
    } else if (c >= 'a' && c <= 'z') {
        v = c - 'a' + 10;
    } else {
        return -1;
    }
    // Ensure the value is within the allowed range for base 36
    return (v < 36) ? v : -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if (jsonObject == null){
        return result;
    }
    try{
        for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
            String key = entry.getKey();
            JsonElement element = entry.getValue();
            Object value;
            if (element == null || element.isJsonNull()){
                value = null;
            }else if (element.isJsonPrimitive()){
                JsonPrimitive prim = element.getAsJsonPrimitive();
                if (prim.isBoolean()){
                    value = prim.getAsBoolean();
                }else if (prim.isNumber()){
                    value = prim.getAsNumber();
                }else{
                    value = prim.getAsString();
                }
            }else if (element.isJsonObject()){
                value = buildContent(element.getAsJsonObject());
            }else{
                // For other JSON types (arrays, etc.) set value to null
                value = null;
            }
            result.put(key, value);
        }
        if (result.containsKey("ats")){
            result.put("ats", System.currentTimeMillis());
        }
    }catch (Exception ex){
        // ignore or handle as needed
    }
    return result;
}

