public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            // Handle escaped backslash first
            if (next == '\\') {
                sb.append('\\');
                i++; // skip next
                continue;
            }
            switch (next) {
                case 'b': sb.append('\b'); i++; break;
                case 't': sb.append('\t'); i++; break;
                case 'n': sb.append('\n'); i++; break;
                case 'f': sb.append('\f'); i++; break;
                case 'r': sb.append('\r'); i++; break;
                case '\'': sb.append('\''); i++; break;
                case '\"': sb.append('\"'); i++; break;
                case 'u':
                    // Unicode escape: exactly four hex digits
                    if (i + 6 > len) {
                        throw new Exception("Invalid unicode escape sequence at index " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence '\\u" + hex + "' at index " + i, e);
                    }
                    i += 5; // skip \uXXXX
                    break;
                default:
                    // Handle octal escapes: one to three octal digits
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int oct = next - '0';
                        int count = 1;
                        // read up to 2 more octal digits
                        while (j + 1 < len && count < 3) {
                            char d = str.charAt(j + 1);
                            if (d >= '0' && d <= '7') {
                                oct = (oct << 3) + (d - '0');
                                j++;
                                count++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) oct);
                        i = j; // skip processed digits
                    } else {
                        // Unknown escape: keep as is
                        sb.append('\\').append(next);
                        i++; // skip next
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

