private int removeUnusedNodesFrom(Category node){
    int removedCount = 0;
    java.util.List<Category> children = node.getChildren();
    if (children != null) {
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()){
            Category child = it.next();
            if (!child.isActive()){
                removedCount += removeAll(child);
                it.remove(); // remove inactive node and its subtree
            } else {
                removedCount += removeUnusedNodesFrom(child);
            }
        }
    }
    return removedCount;
}

private int removeAll(Category node){
    int count = 1; // count the node itself
    java.util.List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += removeAll(child);
        }
    }
    return count;
}

