final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be >= 1");
    }
    // Expect classFileBuffer to be a member of this class
    byte[] cf = classFileBuffer; // assuming accessible
    if (cf == null) {
        throw new IllegalArgumentException("classFileBuffer is null");
    }
    if (cf.length < 8) {
        throw new IllegalArgumentException("classFileBuffer too small to contain header");
    }
    int cpCount = ((cf[6] & 0xFF) << 8) | (cf[7] & 0xFF);
    if (constantPoolEntryIndex >= cpCount) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }
    try {
        int pos = 8; // start after header
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = cf[pos++] & 0xFF;
            switch (tag) {
                case 1: { // CONSTANT_Utf8
                    int len = ((cf[pos] & 0xFF) << 8) | (cf[pos + 1] & 0xFF);
                    pos += 2 + len;
                    break;
                }
                case 3: // CONSTANT_Fieldref
                case 4: // CONSTANT_Methodref
                case 5: // CONSTANT_InterfaceMethodref
                    pos += 4;
                    break;
                case 6: // CONSTANT_String
                case 7: // CONSTANT_Integer
                case 8: // CONSTANT_Float
                    pos += 2;
                    break;
                case 9: // CONSTANT_Long
                case 10: // CONSTANT_Double
                    pos += 8;
                    i++; // these take two entries
                    break;
                case 11: // CONSTANT_NameAndType
                    pos += 4;
                    break;
                case 12: // CONSTANT_MethodHandle
                    pos += 3;
                    break;
                case 13: // CONSTANT_MethodType
                    pos += 2;
                    break;
                case 15: // CONSTANT_Dynamic
                case 16: // CONSTANT_InvokeDynamic
                    pos += 4;
                    break;
                case 18: // CONSTANT_Module
                case 19: // CONSTANT_Package
                    pos += 2;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
            }
        }
        // Now read the target entry
        int tag = cf[pos++] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
        }
        int len = ((cf[pos] & 0xFF) << 8) | (cf[pos + 1] & 0xFF);
        pos += 2;
        if (len > cf.length - pos) {
            throw new IllegalArgumentException("Malformed CONSTANT_Utf8 entry: length exceeds buffer");
        }
        if (charBuffer.length < len) {
            throw new IllegalArgumentException("Provided charBuffer is too small (required " + len + ")");
        }
        String s = new String(cf, pos, len, java.nio.charset.StandardCharsets.UTF_8);
        s.getChars(0, s.length(), charBuffer, 0);
        return s;
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed constant pool: index out of bounds", e);
    } catch (IllegalArgumentException e) {
        throw e;
    } catch (Throwable t) {
        throw new IllegalArgumentException("Unexpected error while reading CONSTANT_Utf8", t);
    }
}

