}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }
    // If the start node itself satisfies the predicate, immediately return it.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }

    // Create the initial circulator at the starting node and set the direction.
    OuterFaceCirculator current = new OuterFaceCirculator(start, dir);

    // Avoid infinite loops by remembering visited nodes.
    Set<Node> visited = new HashSet<>();
    visited.add(start);

    try {
        while (true) {
            Node currentNode = current.getNode();
            // If we've reached the stop node, return the circulator pointing to it.
            if (currentNode.equals(stop)) {
                return current;
            }

            // If the predicate matches, return the current circulator.
            if (predicate.test(currentNode)) {
                return current;
            }

            // Attempt to move to the next node in the specified direction.
            // It's assumed that OuterFaceCirculator has a method to progress the traversal.
            if (!current.next(dir)) {
                // If we cannot move further (e.g., at a boundary), return the current circulator.
                return current;
            }

            // Check for cycles to prevent infinite traversal on malformed data.
            if (!visited.add(current.getNode())) {
                // Node already visited: break to avoid endless loop.
                return current;
            }
        }
    } catch (RuntimeException e) {
        // In case of any unforeseen runtime issue, return the stop circulator as a fallback.
        return new OuterFaceCirculator(stop, dir);
    }
}

