public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }

    // Validate byteArrayValue and byteOffset if array is provided
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset is out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds source array length");
        }
    }

    // Nothing to do if byteLength is zero
    if (byteLength == 0) {
        return this;
    }

    // Ensure capacity
    int newSize = this.size + byteLength;
    if (newSize > this.bytes.length) {
        int newCapacity = Math.max(this.bytes.length << 1, newSize);
        byte[] newBytes = new byte[newCapacity];
        System.arraycopy(this.bytes, 0, newBytes, 0, this.size);
        this.bytes = newBytes;
    }

    // Copy or fill null bytes
    if (byteArrayValue == null) {
        java.util.Arrays.fill(this.bytes, this.size, newSize, (byte) 0);
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.size, byteLength);
    }

    this.size = newSize;
    return this;
}

