public double vertexWeight(Set<V> vertices) {
    if (vertices == null) {
        throw new IllegalArgumentException("Input vertex set cannot be null");
    }
    double sum = 0.0;
    // Assuming the graph maintains an adjacency map where the key is the source vertex
    // and the value is a map of destination vertices to edge weights.
    if (adjacency == null) {
        return sum;
    }
    for (Map.Entry<V, Map<V, Double>> fromEntry : adjacency.entrySet()) {
        Map<V, Double> toMap = fromEntry.getValue();
        if (toMap == null) {
            continue;
        }
        for (Map.Entry<V, Double> toEntry : toMap.entrySet()) {
            if (vertices.contains(toEntry.getKey())) {
                sum += toEntry.getValue();
            }
        }
    }
    return sum;
}

