    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Ensure the first object is Comparable
    if (!(aObj1 instanceof Comparable)) {
        throw new IllegalArgumentException("First argument is not Comparable");
    }
    try {
        @SuppressWarnings("unchecked")
        Comparable<Object> comp = (Comparable<Object>) aObj1;
        return comp.compareTo(aObj2);
    } catch (ClassCastException e) {
        // The objects are not mutually comparable
        throw new IllegalArgumentException("Arguments are not mutually comparable", e);
    }
}

