int addConstantNameAndType(final String name,final String descriptor){
    if(name == null || descriptor == null){
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    // Use a simple composite key to avoid duplicate entries
    final String key = name + '\0' + descriptor;
    Integer existingIndex = nameAndTypeIndices.get(key);
    if(existingIndex != null){
        // Already present, just return the existing index
        return existingIndex;
    }
    synchronized (this){
        // Check again inside the synchronized block to avoid race conditions
        existingIndex = nameAndTypeIndices.get(key);
        if(existingIndex != null){
            return existingIndex;
        }
        // Add UTF8 entries for name and descriptor (helper method assumed to exist)
        int nameIndex = addUtf8(name);
        int descriptorIndex = addUtf8(descriptor);
        // Create the constant pool entry (class assumed to exist)
        ConstantPoolEntry entry = new NameAndTypeInfo(nameIndex, descriptorIndex);
        int newIndex = constantPool.size();
        constantPool.add(entry);
        nameAndTypeIndices.put(key, newIndex);
        return newIndex;
    }
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); ) {
        char c = input.charAt(i);
        if (c != '\\') {
            sb.append(c);
            i++;
            continue;
        }
        // Backslash detected
        if (i + 1 >= input.length()) {
            // Lone backslash at end; treat as literal
            sb.append('\\');
            i++;
            continue;
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i += 2;
                break;
            case 't':
                sb.append('\t');
                i += 2;
                break;
            case 'r':
                sb.append('\r');
                i += 2;
                break;
            case 'b':
                sb.append('\b');
                i += 2;
                break;
            case 'f':
                sb.append('\f');
                i += 2;
                break;
            case '\\':
                sb.append('\\');
                i += 2;
                break;
            case '"':
                sb.append('\"');
                i += 2;
                break;
            case '\'':
                sb.append('\'');
                i += 2;
                break;
            case 'x': {
                int start = i + 2;
                int hexLen = 0;
                while (start + hexLen < input.length() && hexLen < 2) {
                    char ch = input.charAt(start + hexLen);
                    boolean isHex = (ch >= '0' && ch <= '9')
                            || (ch >= 'A' && ch <= 'F')
                            || (ch >= 'a' && ch <= 'f');
                    if (!isHex) {
                        break;
                    }
                    hexLen++;
                }
                if (hexLen > 0) {
                    try {
                        int code = Integer.parseInt(input.substring(start, start + hexLen), 16);
                        sb.append((char) code);
                        i = start + hexLen;
                    } catch (NumberFormatException e) {
                        // Default to literal if parsing fails
                        sb.append('x');
                        i += 2;
                    }
                } else {
                    sb.append('x');
                    i += 2;
                }
                break;
            }
            case 'u': {
                int start = i + 2;
                if (start + 4 <= input.length()) {
                    boolean allHex = true;
                    for (int k = start; k < start + 4; k++) {
                        char ch = input.charAt(k);
                        boolean isHex = (ch >= '0' && ch <= '9')
                                || (ch >= 'A' && ch <= 'F')
                                || (ch >= 'a' && ch <= 'f');
                        if (!isHex) {
                            allHex = false;
                            break;
                        }
                    }
                    if (allHex) {
                        try {
                            int code = Integer.parseInt(input.substring(start, start + 4), 16);
                            sb.append((char) code);
                            i = start + 4;
                            break;
                        } catch (NumberFormatException e) {
                            // fall through to default handling
                        }
                    }
                }
                sb.append('u');
                i += 2;
                break;
            }
            default:
                // Unrecognized escape; treat following character literally
                sb.append(next);
                i += 2;
                break;
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null
    if (array1 == null && array2 == null) {
        return null;
    }
    // If one of the arrays is null, return a copy of the non-null array
    if (array1 == null) {
        String[] result = new String[array2.length];
        System.arraycopy(array2, 0, result, 0, array2.length);
        return result;
    }
    if (array2 == null) {
        String[] result = new String[array1.length];
        System.arraycopy(array1, 0, result, 0, array1.length);
        return result;
    }
    // Both arrays are non-null: concatenate them
    String[] result = new String[array1.length + array2.length];
    System.arraycopy(array1, 0, result, 0, array1.length);
    System.arraycopy(array2, 0, result, array1.length, array2.length);
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel is out of range");
    }
    if (minLabel == 0) {
        // nothing to move, already in bucket 0
        return;
    }
    Set<Integer> src = bucketsByLabel.get(minLabel);
    if (src == null || src.isEmpty()) {
        return;
    }
    Set<Integer> dst = bucketsByLabel.get(0);
    if (dst == null) {
        dst = new java.util.HashSet<>();
        bucketsByLabel.set(0, dst);
    }
    for (Integer v : src) {
        if (v == null) {
            continue;
        }
        dst.add(v);
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }
    src.clear();
}

