private void pop(final int elements) {
    // Validate input
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non‑negative, got " + elements);
    }

    try {
        for (int i = 0; i < elements; i++) {
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException(
                    "Output frame stack underflow: attempted to pop " + elements +
                    " elements, but only " + (i) + " could be removed.");
            }
            outputFrameStack.pop();
        }
    } catch (RuntimeException e) {
        // Wrap any runtime exception to ensure method contract is respected
        throw new RuntimeException("Failed to pop " + elements + " abstract types from the output frame stack", e);
    }
}

public boolean isCompatible(DataTable dataset){
    if (dataset == null){
        return false;
    }
    try{
        java.lang.Object otherBucket = null;
        try{
            java.lang.reflect.Method m = dataset.getClass().getMethod("getBucket");
            otherBucket = m.invoke(dataset);
        }catch(Exception e){
            try{
                java.lang.reflect.Field f = dataset.getClass().getDeclaredField("bucket");
                f.setAccessible(true);
                otherBucket = f.get(dataset);
            }catch(Exception ex){
                return false;
            }
        }
        java.lang.Object thisBucket = null;
        try{
            java.lang.reflect.Method m = this.getClass().getMethod("getBucket");
            thisBucket = m.invoke(this);
        }catch(Exception e){
            try{
                java.lang.reflect.Field f = this.getClass().getDeclaredField("bucket");
                f.setAccessible(true);
                thisBucket = f.get(this);
            }catch(Exception ex){
                return false;
            }
        }
        if (thisBucket == null){
            return otherBucket == null;
        }
        return thisBucket.equals(otherBucket);
    }catch(Exception e){
        return false;
    }
}

