void removeSelf() {
    try {
        // Detach from a doubly‑linked list if this bucket participates in one.
        if (prev != null) {
            prev.next = this.next;
        }
        if (next != null) {
            next.prev = this.prev;
        }

        // Null out local references to help the garbage collector.
        next = null;
        prev = null;

        // If the bucket knows its container (e.g., a hash table or bucket list),
        // give the container a chance to update its bookkeeping.
        if (container != null) {
            // The container is expected to have a method that handles
            // the removal of its constituent bucket.
            container.onBucketRemoved(this);
        }
    } catch (Exception e) {
        // Silently swallow any unexpected runtime problems to avoid
        // disrupting the surrounding infrastructure.
        // In a real application you might log the exception here.
    }
}

