private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    try {
        // Detach from the list
        ListNodeImpl<E> prev = node.prev;
        ListNodeImpl<E> next = node.next;

        if (prev != null) {
            prev.next = next;
        } else {
            // node was the head
            this.head = next;
        }

        if (next != null) {
            next.prev = prev;
        } else {
            // node was the tail
            this.tail = prev;
        }

        // Clear the node's pointers
        node.prev = null;
        node.next = null;

        // Update size
        if (this.size > 0) {
            this.size--;
        }

        return true;
    } catch (Exception e) {
        // Unexpected error while unlinking
        return false;
    }
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> result = new ArrayList<>();
    try {
        // Assume a method or field that provides the current profiles
        List<Profile> profiles = getCurrentProfiles();
        if (profiles == null) {
            return result; // nothing to build
        }
        for (Profile profile : profiles) {
            if (profile == null) {
                continue; // skip null entries
            }
            // Assume each profile has a segment snapshot search component
            SegmentSnapshotSearch snapshotSearch = profile.getSegmentSnapshotSearch();
            if (snapshotSearch == null) {
                continue;
            }
            // Obtain sequence ranges from the snapshot search
            List<SequenceRange> ranges = snapshotSearch.computeSequenceRanges();
            if (ranges != null && !ranges.isEmpty()) {
                result.addAll(ranges);
            }
        }
    } catch (Exception e) {
        // Wrap and re‑throw a runtime exception with context
        throw new RuntimeException("Unable to build sequence ranges", e);
    }
    return result;
}

