private String parseToken(final char[] terminators){
    // Validate input
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array cannot be null");
    }

    // Ensure the source buffer exists
    if (buffer == null) {
        throw new IllegalStateException("buffer is not initialized");
    }

    StringBuilder token = new StringBuilder();
    while (pos < buffer.length()) {
        char current = buffer.charAt(pos);
        boolean isTerminator = false;
        for (char term : terminators) {
            if (current == term) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        token.append(current);
        pos++;
    }
    return token.toString();
}

public static String trimLeadingCharacter(String str, char leadingCharacter) {
    // Return null if the input string is null to avoid NullPointerException
    if (str == null) {
        return null;
