    int length = str.length();
    int index = 0;

    // Find the first character that is not the leadingCharacter
    while (index < length && str.charAt(index) == leadingCharacter) {
        index++;
    }

    // Substring from the first non-leading character (or empty if all were trimmed)
    return str.substring(index);
}

