            return ((java.util.Map<?,?>)val).containsKey(name);
        } else if (val instanceof java.util.Set) {
            return ((java.util.Set<?>)val).contains(name);
        }
    } catch (NoSuchFieldException e) {
        // Field not found, ignore
    } catch (IllegalAccessException e) {
        // Cannot access field, ignore
    } catch (Exception e) {
        // Other exception, ignore
    }
    try {
        java.lang.reflect.Method m = this.getClass().getMethod("getVariables");
        Object ret = m.invoke(this);
        if (ret instanceof java.util.Collection) {
            return ((java.util.Collection<?>)ret).contains(name);
        }
    } catch (Throwable e) {
        // Method not found or invocation error, ignore
    }
    return false;
}

