public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }

    SwingUtilities.invokeLater(() -> {
        try {
            // Select the specified row
            table.setRowSelectionInterval(row, row);

            // Find the rectangle for the first column of the row to ensure it becomes visible
            Rectangle rect = table.getCellRect(row, 0, true);
            if (rect != null) {
                table.scrollRectToVisible(rect);
            }

            // Repaint the table after layout changes
            table.revalidate();
            table.repaint();
        } catch (Exception e) {
            // Log or handle unexpected runtime issues gracefully
            e.printStackTrace();
        }
    });
}

public ByteVector putInt(final int intValue){
    int newOffset = offset + 4;
    if (newOffset > buffer.length) {
        buffer = java.util.Arrays.copyOf(buffer, Math.max(buffer.length * 2, newOffset));
    }
    buffer[offset++] = (byte) (intValue >>> 24);
    buffer[offset++] = (byte) (intValue >>> 16);
    buffer[offset++] = (byte) (intValue >>> 8);
    buffer[offset++] = (byte) intValue;
    return this;
}

