private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("vertices must not be null");
    }

    // A set with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    for (int i = 0; i < n; i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            // In an undirected graph we need an edge in either direction.
            // In a directed graph we consider either orientation as sufficient
            // for the purpose of detecting a clique in the induced subgraph.
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private <K extends Comparable<? super K>> List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    int size = keys.size();
    List<Integer> lowerBoundIndices = new ArrayList<>(size);
    for (int i = 0; i < size; i++) {
        K current = keys.get(i);
        int maxLowerIdx = -1;
        for (int j = 0; j < size; j++) {
            if (i == j) continue;
            K other = keys.get(j);
            if (other.compareTo(current) < 0) { // other < current
                if (maxLowerIdx == -1 || other.compareTo(keys.get(maxLowerIdx)) > 0) {
                    maxLowerIdx = j;
                }
            }
        }
        lowerBoundIndices.add(maxLowerIdx);
    }
    return lowerBoundIndices;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor is null");
    }
    int pos = 0;
    Deque<Object> stack = this.outputStack; // Assumes a field named outputStack exists in the enclosing class
    boolean readingArgs = false;
    try {
        if (descriptor.charAt(0) == '(') {
            pos = 1;
            readingArgs = true;
        }
        while (pos < descriptor.length()) {
            if (readingArgs && descriptor.charAt(pos) == ')') {
                break; // end of argument list; return type is ignored
            }
            // Skip array brackets
            while (descriptor.charAt(pos) == '[') {
                pos++;
            }
            char c = descriptor.charAt(pos);
            int slots;
            if (c == 'L') { // object or interface type
                int semicolon = descriptor.indexOf(';', pos);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Malformed descriptor: " + descriptor);
                }
                slots = 1;
                pos = semicolon + 1;
            } else if (c == 'J' || c == 'D') { // long or double occupy two slots
                slots = 2;
                pos++;
            } else { // other primitive types occupy one slot
                slots = 1;
                pos++;
            }
            for (int i = 0; i < slots; i++) {
                if (stack.isEmpty()) {
                    throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
                }
                stack.pop();
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed descriptor: " + descriptor, e);
    }
}

