public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null) {
        throw new IllegalArgumentException("relativePath cannot be null");
    }

    // If relativePath is empty or just a dot, return the original path unchanged
    String trimmedRel = relativePath.trim();
    if (trimmedRel.isEmpty() || trimmedRel.equals(".")) {
        return path;
    }

    // Determine if the original path is absolute (starts with '/')
    boolean isAbsolute = path.startsWith("/");

    // Split the path into segments, ignoring empty segments resulting from leading/trailing slashes
    String[] pathSegs = path.split("/");
    // Use a dynamic list to track the current path segments
    java.util.List<String> current = new java.util.ArrayList<>();
    for (String seg : pathSegs) {
        if (!seg.isEmpty()) {
            current.add(seg);
        }
    }

    // Split the relative path into segments
    String[] relSegs = trimmedRel.split("/");
    for (String seg : relSegs) {
        if (seg.isEmpty() || seg.equals(".")) {
            // No-Op: ignore empty or single-dot segments
            continue;
        } else if (seg.equals("..")) {
            // Navigate up one level: remove last segment if possible
            if (!current.isEmpty()) {
                current.remove(current.size() - 1);
            }
        } else {
            // Append a new directory/file component
            current.add(seg);
        }
    }

    // Reconstruct the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append('/');
    }
    for (int i = 0; i < current.size(); i++) {
        result.append(current.get(i));
        if (i < current.size() - 1) {
            result.append('/');
        }
    }

    // Handle the case where all segments were removed (e.g., resolves to root)
    return result.length() == 0 ? (isAbsolute ? "/" : "") : result.toString();
}

