static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            if (!(obj instanceof String)) {
                throw new IllegalArgumentException("Array contains non-String element");
            }
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        // All elements are non-null and already strings
        return (String[]) array;
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastSep = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    return (dotIndex > lastSep) ? dotIndex : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            return true;
        }
        long currentTime = System.currentTimeMillis();
        long elapsed = currentTime - timestamp;
        if (elapsed < 0) {
            return false;
        }
        return elapsed >= expiredThreshold;
    } catch (Exception e) {
        return false;
    }
}

Edge edgeToNext(){
    try{
        /* Retrieve the nodes that should form the edge.  The exact method names depend
           on the surrounding class but the logic is the same: we need the node that
           was last returned and the node that will be returned next. */
        Node previousNode = getPreviousReturnedNode();
        Node nextNode      = getNextReturnedNode();

        if(previousNode==null || nextNode==null){
            throw new IllegalStateException("Previous or next node not available for edge construction.");
        }

        /* Resolve the real counterpart if the node is virtual.  These helper
           methods are assumed to exist in the surrounding code. */
        Node realPrevious = previousNode.isVirtual() ? previousNode.getRealCounterpart() : previousNode;
        Node realNext     = nextNode.isVirtual()     ? nextNode.getRealCounterpart()  : nextNode;

        /* Find the edge that connects the two real nodes.  If it is not found
           we throw an informative exception. */
        Edge e = findEdgeBetween(realPrevious, realNext);
        if(e==null){
            throw new NoSuchElementException(
                "Edge connecting " + realPrevious + " and " + realNext + " does not exist.");
        }

        return e;
    }catch(RuntimeException | IllegalStateException | NoSuchElementException e){
        /* Re‑throw the known runtime problems with a clear message. */
        throw e;
    }catch(Exception e){
        /* Unexpected errors are wrapped in a RuntimeException to avoid checked
           exceptions for the caller. */
        throw new RuntimeException("Failed to retrieve edge to next node", e);
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (subLen > strLen) {
        return false;
    }
    if (index < 0 || index > strLen - subLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    // Guard against null events
    if (event == null) {
        return;
    }

    // Convert the log event to a signed message string
    String message = event.getRenderedMessage();
    if (message == null) {
        message = "";
    }

    // Append a newline so that each message terminates on the client side
    message += System.lineSeparator();
    byte[] bytes = message.getBytes(java.nio.charset.StandardCharsets.UTF_8);

    // Iterate over the currently connected clients and send the message
    // If a client fails to receive the data, remove it from the list
    synchronized (clients) {
        java.util.Iterator<java.net.Socket> it = clients.iterator();
        while (it.hasNext()) {
            java.net.Socket socket = it.next();
            try {
                java.io.OutputStream out = socket.getOutputStream();
                out.write(bytes);
                out.flush();
            } catch (java.io.IOException ioEx) {
                // Client failed; close socket and remove from collection
                it.remove();
                try {
                    socket.close();
                } catch (java.io.IOException ignored) {
                }
            }
        }
    }
}

