    } catch (java.io.EOFException e) {
        return 0;
    }
}

private String buildContentRange() {
    try {
        // Assume the following class fields exist and are initialized correctly:
        // long contentStart, contentEnd, contentSize;   // contentSize can be -1 if unknown
        if (contentStart < 0 || contentEnd < 0) {
            throw new IllegalArgumentException("Content range indices must be non‑negative");
        }
        if (contentEnd < contentStart) {
            throw new IllegalArgumentException("ContentRange end must not be smaller than start");
        }
        if (contentSize >= 0 && contentEnd >= contentSize) {
            throw new IllegalArgumentException("ContentRange end must be less than total size");
        }

        if (contentSize < 0) {
            // Size unknown – use wildcard as per RFC 7233 §4.2
            return "bytes " + contentStart + "-" + contentEnd + "/*";
        }
        return "bytes " + contentStart + "-" + contentEnd + "/" + contentSize;
    } catch (Exception e) {
        // In case of any unexpected issue, return a safe default
        return "bytes */*";
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new java.util.ArrayList<>();
    if (file == null || !file.isFile()) {
        return snapshots;
    }
    java.util.List<ProfileAnalyzeTimeRange> ranges = (timeRanges == null) ? java.util.Collections.emptyList() : timeRanges;
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Assume the line format: "<timestamp>,<snapshot data>"
            String[] parts = line.split(",", 2);
            if (parts.length < 2) {
                continue;
            }
            long ts;
            try {
                ts = Long.parseLong(parts[0].trim());
            } catch (NumberFormatException e) {
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : ranges) {
                try {
                    java.lang.reflect.Method startMethod = range.getClass().getMethod("getStartTime");
                    java.lang.reflect.Method endMethod = range.getClass().getMethod("getEndTime");
                    Object startObj = startMethod.invoke(range);
                    Object endObj = endMethod.invoke(range);
                    if (startObj instanceof Number && endObj instanceof Number) {
                        long start = ((Number) startObj).longValue();
                        long end = ((Number) endObj).longValue();
                        if (ts >= start && ts <= end) {
                            inRange = true;
                            break;
                        }
                    }
                } catch (Exception ignore) {
                }
            }
            if (!inRange) {
                continue;
            }
            // Try to parse the snapshot
            try {
                java.lang.reflect.Method parseMethod = ThreadSnapshot.class.getMethod("parse", String.class);
                Object parsed = parseMethod.invoke(null, parts[1].trim());
                if (parsed instanceof ThreadSnapshot) {
                    snapshots.add((ThreadSnapshot) parsed);
                    continue;
                }
            } catch (Exception e) {
            }
            try {
                java.lang.reflect.Constructor<ThreadSnapshot> ctor = ThreadSnapshot.class.getConstructor(String.class);
                snapshots.add(ctor.newInstance(parts[1].trim()));
            } catch (Exception ignored) {
            }
        }
    }
    return snapshots;
}
